{"file_path":"src/simulate.js","content":"function makeRunner(policy) {
  const states = new Map()

  if (policy.kind === 'bucket') {
    const cap = policy.capacity * policy.per
    return {
      name: policy.name,
      advance(key, tick) {
        let state = states.get(key)
        if (state === undefined) {
          state = { num: cap, last: tick }
          states.set(key, state)
          return
        }
        const elapsed = tick - state.last
        if (elapsed > 0n) {
          let num = state.num + policy.refill * elapsed
          if (num > cap) num = cap
          state.num = num
        }
        state.last = tick
      },
      allows(key) {
        return states.get(key).num >= policy.per
      },
      record(key) {
        const state = states.get(key)
        state.num -= policy.per
      },
    }
  }

  return {
    name: policy.name,
    advance(key, tick) {
      let state = states.get(key)
      if (state === undefined) {
        state = { ticks: [] }
        states.set(key, state)
      }
      const cutoff = tick - policy.span
      let drop = 0
      while (drop < state.ticks.length && state.ticks[drop] <= cutoff) drop += 1
      if (drop > 0) state.ticks.splice(0, drop)
    },
    allows(key) {
      return BigInt(states.get(key).ticks.length) < policy.limit
    },
    record(key, tick) {
      states.get(key).ticks.push(tick)
    },
  }
}

export function simulate({ policies, routes, events }) {
  const runners = new Map()
  for (const [name, policy] of policies) runners.set(name, makeRunner(policy))

  const prefixes = [...routes.keys()]

  return events.map(({ tick, key }) => {
    let best = null
    for (const prefix of prefixes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = prefix
    }
    if (best === null) return { tick, key, allowed: true, by: null }

    const chain = routes.get(best).map((name) => runners.get(name))
    for (const runner of chain) runner.advance(key, tick)
    let denier = null
    for (const runner of chain) {
      if (!runner.allows(key)) {
        denier = runner.name
        break
      }
    }
    if (denier !== null) return { tick, key, allowed: false, by: denier }
    for (const runner of chain) runner.record(key, tick)
    return { tick, key, allowed: true, by: null }
  })
